const CFG={
  SECRET:'REPLACE_WITH_YOUR_SECRET',
  BASE_URL:'http://chatwoot-rails-1:3000',
  MAX_LEN:2000,
  TEST_MODE:false,
  TEST_CONTACT_ID:18676,
  BOT_SENDER_ID:2,
  BLOCKED_INBOX_IDS:[12,16,19],
  DUPLICATE_INBOXES:{},
  DEDUP_WINDOW_SEC:3600,
  CHATWOOT_API_TOKEN:'REPLACE_WITH_YOUR_SECRET',

  // ── Inbox → WhatsApp phone_number_id mapping ──
  INBOX_TO_PHONE_NUMBER_ID: {
    10: '1111231948738550',
    11: '1015579888315502',
    12: '963488543523802',
    16: '1123949100810776',
    19: '1243217355535246'
  },

  // ── STOP NOTICE: inbox 10 (01000000000) — WhatsApp stopped, calls still work ──
  STOP_NOTICE_INBOX_ID: 10,
  STOP_NOTICE_TEXT:
    'تنبيه مهم: تم إيقاف الواتساب على هذا الرقم.\n' +
    'المكالمات ما زالت تعمل على نفس الرقم.\n' +
    'للواتساب، يرجى التواصل على: 01000000000\n' +
    'ورقم التسليمات كما هو: 01000000000.'
};
const S=require('/files/bot_state_v2.js');
const req=$input.first().json;
const q=req.query||{};
if(q.token!==CFG.SECRET)return[];
const b=req.body||{};

// ─────────────────────────────────────────────────────────
// Handle conversation_status_changed
// ─────────────────────────────────────────────────────────
if(b.event==='conversation_status_changed'){
  const conv=b.conversation||{};
  const convId=String(conv.id||'');
  const accountId=(b.account||{}).id;
  if(!accountId||!convId)return[];
  const newStatus=String(conv.status||'');
  if(newStatus!=='snoozed'&&newStatus!=='resolved')return[];

  const key=S.contactKey(b);
  console.log(`[Gate] status_changed → ${newStatus} for ${key} — disabling bot`);

  await S.run(r=>S.update(r,key,st=>{
    st.botDisabledPermanently=true;
    st.lastBotActionBatch=null;
    st.state='HANDED_OFF';
    st.handoffReason=st.handoffReason||('status_'+newStatus);
    st.handedOffAt=st.handedOffAt||Date.now();
    return st;
  }));
  await S.run(r=>S.logEvent(r,key,'handoff',{reason:'status_'+newStatus,source:'chatwoot_webhook'}));
  return[];
}

if(b.event!=='message_created')return[];
const accountId=(b.account||{}).id;
const conv=b.conversation||{};
const convId=String(conv.id||'');
if(!accountId||!convId)return[];

const inboxId=(b.inbox||{}).id;

// ─────────────────────────────────────────────────────────
// ── COUNT SENT MESSAGES (per phone_number_id + aggregate) ──
// ─────────────────────────────────────────────────────────
const isOutgoingPrecheck = b.message_type === 'outgoing' || b.message_type === 1;
if (isOutgoingPrecheck && !b.private) {
  const today = new Date().toISOString().slice(0, 10);
  const month = today.slice(0, 7);
  const phoneNumberId = CFG.INBOX_TO_PHONE_NUMBER_ID[inboxId] || null;
  const contactKey = S.contactKey(b);

  const dailyKey        = `msgcount:daily:${today}:sent`;
  const monthlyKey      = `msgcount:monthly:${month}:service`;
  const convKey         = `msgcount:conv:${contactKey}:sent`;
  const dailyPhoneKey   = phoneNumberId ? `msgcount:daily:${today}:phone:${phoneNumberId}:sent` : null;
  const monthlyPhoneKey = phoneNumberId ? `msgcount:monthly:${month}:phone:${phoneNumberId}:service` : null;

  const stats = await S.run(async r => {
    const d = await r.incr(dailyKey);
    const m = await r.incr(monthlyKey);
    const c = await r.incr(convKey);
    await r.expire(dailyKey, 7776000);
    await r.expire(monthlyKey, 31536000);
    await r.expire(convKey, 31536000);

    let dp = 0, mp = 0;
    if (dailyPhoneKey)   { dp = await r.incr(dailyPhoneKey);   await r.expire(dailyPhoneKey, 7776000); }
    if (monthlyPhoneKey) { mp = await r.incr(monthlyPhoneKey); await r.expire(monthlyPhoneKey, 31536000); }

    return { dailyTotal: d, monthlyTotal: m, convTotal: c, dailyPhone: dp, monthlyPhone: mp };
  });

  console.log(`[Gate] Sent: inbox=${inboxId} phone_id=${phoneNumberId || 'unmapped'} today=${stats.dailyTotal} month=${stats.monthlyTotal} conv=${stats.convTotal} phone_today=${stats.dailyPhone} phone_month=${stats.monthlyPhone}`);
}

// ── Inbox filtering for bot processing (counter already ran) ──
if(CFG.BLOCKED_INBOX_IDS.includes(inboxId)){
  console.log(`[Gate] Inbox ${inboxId} blocked from bot processing (message already counted)`);
  return [];
}

if(CFG.DUPLICATE_INBOXES&&CFG.DUPLICATE_INBOXES[inboxId]){
  console.log(`[Gate] Skipping mirror inbox ${inboxId}`);
  return null;
}

const contactId=((conv.meta||{}).sender||{}).id;
if(CFG.TEST_MODE&&String(contactId)!==String(CFG.TEST_CONTACT_ID))return[];

const now=Date.now();
const key=S.contactKey(b);
const isIncoming=b.message_type==='incoming'||b.message_type===0;
const isOutgoing=b.message_type==='outgoing'||b.message_type===1;
const msgId=String(b.id||'');
const attachments=b.attachments||[];
let text=String(b.content||'').trim();

// Human outgoing events invalidate any pending bot notice
if (isOutgoing && b.private !== true && ['user','agent'].includes((b.sender||{}).type) && (b.sender||{}).id !== CFG.BOT_SENDER_ID) {
  await S.run(r=>S.update(r,key,st=>{st.state='HANDED_OFF';st.botDisabledPermanently=true;st.lastBotActionBatch=null;st.handoffReason='human_replied';st.handedOffAt=now;return st;}));
  return [];
}

// ─────────────────────────────────────────────────────────
// ── STOP NOTICE for inbox 10 (01000000000) — NEW CONVOS ONLY ──
// First time we ever see this conversation on inbox 10:
//   → emit a special payload that will be routed by "IF: Stop Notice?"
//     to send the notice + resolve the conversation + disable bot. No AI.
// Existing conversations (marked beforehand via migration) → skip.
// ─────────────────────────────────────────────────────────
if (inboxId === CFG.STOP_NOTICE_INBOX_ID && isIncoming && !b.private) {
  const seenKey = `stop_notice_seen:${accountId}:${convId}`;
  const firstTime = await S.run(r => r.set(seenKey, '1', 'EX', 60 * 60 * 24 * 365, 'NX'));

  if (firstTime === 'OK') {
    console.log(`[Gate] STOP NOTICE triggered for inbox 10 (conv ${convId}) — new conversation`);

    // Persist bot-disable state immediately so nothing downstream re-enables it.
    await S.run(r => S.update(r, key, st => {
      st.state = 'RESOLVED';
      st.handoffReason = 'number_deprecation_notice';
      st.handedOffAt = now;
      st.resolvedAt = now;
      st.botDisabledPermanently = true;
      return st;
    }));

    return [{
      json: {
        __stopNotice: true,
        __stopNoticeText: CFG.STOP_NOTICE_TEXT,
        contactKey: key,
        accountId,
        conversationId: convId,
        baseUrl: CFG.BASE_URL,
        inboxId
      }
    }];
  }

  // Already handled → do nothing, keep bot disabled.
  console.log(`[Gate] STOP NOTICE already handled for inbox 10 (conv ${convId}) — skipping`);
  return null;
}

// ── EARLY CHECK 1 ──
const earlyState = (await S.run(r => S.get(r, key))) || {};
if (earlyState.botDisabledPermanently) {
  console.log(`[Gate] Bot permanently disabled for ${key} — skipping`);
  return null;
}

// ── EARLY CHECK 2 ──
if (earlyState.state === 'HANDED_OFF' && !earlyState.botDisabledPermanently) {
  console.log(`[Gate] HANDED_OFF without flag — healing state for ${key}`);
  await S.run(r => S.update(r, key, st => {
    st.botDisabledPermanently = true;
    st.lastBotActionBatch = null;
    return st;
  }));
  return null;
}

// ── Human assignee guard ──
const assigneeId = (conv.meta||{}).assignee && (conv.meta||{}).assignee.id;
if (assigneeId) {
  console.log(`[Gate] Human assigned (${assigneeId}) for ${key} — disabling bot`);
  await S.run(r => S.update(r, key, st => {
    st.botDisabledPermanently = true;
    st.state = 'HANDED_OFF';
    st.handoffReason = st.handoffReason || 'human_assigned';
    st.handedOffAt = st.handedOffAt || now;
    return st;
  }));
  await S.run(r => S.logEvent(r, key, 'handoff', { reason: 'human_assigned', assignee_id: assigneeId }));
  return null;
}

// ── Egyptian phone normalization ──
function normalizePhoneForStorage(p){
  if(!p) return '';
  let s = String(p).replace(/[^0-9]/g,'');
  if (s.startsWith('20') && s.length >= 11) s = s.slice(2);
  if (s.startsWith('0')) s = s.slice(1);
  if (s.length === 10) return '0' + s;
  return s;
}
function normalizePhoneMatch(p){
  if(!p) return '';
  return String(p).replace(/[^0-9]/g,'').replace(/^0+/,'').replace(/^20/,'');
}

const senderPhoneRaw=String(
  (b.sender||{}).phone_number ||
  ((conv.meta||{}).sender||{}).phone_number ||
  ''
);
const senderPhoneNorm=normalizePhoneMatch(senderPhoneRaw);
const senderPhoneStored=normalizePhoneForStorage(senderPhoneRaw);

// ── WhatsApp username ──
const senderAttrs = (b.sender || {}).additional_attributes || {};
const convAttrs = ((conv.meta || {}).sender || {}).additional_attributes || {};
const waUsername = String(
  senderAttrs.social_whatsapp_user_name ||
  (senderAttrs.social_profiles || {}).whatsapp ||
  convAttrs.social_whatsapp_user_name ||
  (convAttrs.social_profiles || {}).whatsapp ||
  ''
).trim().replace(/^@/, '').toLowerCase();

const identityKey =
  senderPhoneNorm ||
  (waUsername ? `wa:${waUsername}` : `cid:${contactId}`);

console.log(`[Gate] inbox=${inboxId} msgId=${msgId} contact=${contactId} phone=${senderPhoneStored||'(none)'} wa=${waUsername||'(none)'} identity=${identityKey}`);

// ── Better filename extraction from URL ──
function extractFilenameFromUrl(url) {
  try {
    const u = new URL(url);
    const segments = u.pathname.split('/').filter(Boolean);

    for (let i = segments.length - 1; i >= 0; i--) {
      const seg = decodeURIComponent(segments[i]);
      if (/\.[a-z0-9]{2,5}$/i.test(seg)) return seg;
    }

    const last = segments[segments.length - 1] || '';
    const decoded = decodeURIComponent(last);
    if (decoded && !/^\d+$/.test(decoded) && !['upload', 'download', 'file', 'view'].includes(decoded.toLowerCase())) {
      return decoded;
    }

    return `file_${Date.now().toString(36)}_${Math.random().toString(36).slice(2,6)}`;
  } catch (e) {
    return `file_${Date.now().toString(36)}`;
  }
}

// ── PRIVATE NOTES → capture ANY URL as internal media ──
if(b.private===true){
  const urls=String(b.content||'').match(/https?:\/\/[^\s]+/g)||[];
  if(urls.length>0){
    await S.run(r=>S.update(r,key,st=>{
      st.media=st.media||{urls:[],count:0};
      let pushed=0;
      for(const url of urls){
        const base=url.split('?')[0];
        if(st.media.urls.some(m=>m.url&&m.url.split('?')[0]===base))continue;
        let host='';
        try{host=new URL(url).hostname;}catch(e){}

        const name = extractFilenameFromUrl(url);

        st.media.urls.push({
          url,name,
          type: inferTypeFromName(name) || 'file',
          source:'internal_note',
          host,
          sentAt:now,msgId,
          analyzed:null,notes:''
        });
        pushed++;
      }
      if(pushed>0){
        st.media.count=(st.media.count||0)+pushed;
        st.media.lastMediaAt=now;
        st.pendingInternalMedia=true;
      }
      return st;
    }));
  }
  return null;
}

// ── File extension → type inference ──
function inferTypeFromName(name) {
  const clean = String(name || '').split('?')[0].toLowerCase();
  const m = clean.match(/\.([a-z0-9]{2,5})$/);
  if (!m) return null;
  const ext = m[1];
  if (['jpg','jpeg','png','webp','gif','bmp','tif','tiff','heic','heif','avif','jfif','svg'].includes(ext)) return 'image';
  if (['mp3','wav','ogg','m4a','aac','opus','flac'].includes(ext)) return 'audio';
  if (['mp4','m4v','mov','webm','mkv','avi','mpeg','mpg','3gp','ts','flv','wmv'].includes(ext)) return 'video';
  if (ext === 'pdf') return 'pdf';
  if (['doc','docx','odt','rtf'].includes(ext)) return 'doc';
  if (['xls','xlsx','ods','csv'].includes(ext)) return 'doc';
  if (['ppt','pptx','odp'].includes(ext)) return 'doc';
  if (['txt','text','log','json','md','xml','html'].includes(ext)) return 'text';
  if (['rar','zip','7z'].includes(ext)) return 'archive';
  if (['ai','psd','psb','eps','plt','dwg','dxf','ps'].includes(ext)) return 'design_file';
  return null;
}

function chatwootFileType(val) {
  const n = Number(val);
  if (n === 0) return 'image';
  if (n === 1) return 'audio';
  if (n === 2) return 'video';
  if (n === 3) return 'file';
  if (n === 4) return 'location';
  if (n === 8) return 'contact';
  const s = String(val || '').toLowerCase();
  if (s === 'image') return 'image';
  if (s === 'audio') return 'audio';
  if (s === 'video') return 'video';
  if (s === 'file') return 'file';
  if (s === 'sticker') return 'sticker';
  return 'file';
}

function resolveMediaType(att) {
  const byName = inferTypeFromName(att.file_name || att.file_url || '');
  if (byName) return byName;
  const ft = chatwootFileType(att.file_type);
  if (ft === 'image') return 'image';
  if (ft === 'audio') return 'audio';
  if (ft === 'video') return 'video';
  if (ft === 'sticker') return 'sticker';
  return 'file';
}

function fileKey(name,size){return String(name||'').trim().toLowerCase()+'|'+Number(size||0);}

async function postPublicMessage(aId,cId,content){
  try{
    await this.helpers.httpRequest({
      method:'POST',
      url:`${CFG.BASE_URL}/api/v1/accounts/${aId}/conversations/${cId}/messages`,
      headers:{
        'Content-Type':'application/json',
        'api_access_token':CFG.CHATWOOT_API_TOKEN,
        'X-Forwarded-Proto':'https',
        'X-Forwarded-Ssl':'on'
      },
      body:{content,message_type:'outgoing',private:false},
      json:true
    });
  }catch(e){console.log(`[Gate] public fail: ${String(e.message||e)}`);}
}

async function resolveConversation(aId,cId){
  try{
    await this.helpers.httpRequest({
      method:'POST',
      url:`${CFG.BASE_URL}/api/v1/accounts/${aId}/conversations/${cId}/toggle_status`,
      headers:{
        'Content-Type':'application/json',
        'api_access_token':CFG.CHATWOOT_API_TOKEN,
        'X-Forwarded-Proto':'https',
        'X-Forwarded-Ssl':'on'
      },
      body:{status:'resolved'},
      json:true
    });
  }catch(e){console.log(`[Gate] resolve fail: ${String(e.message||e)}`);}
}

const out=await S.run(async r=>{
  if(msgId){
    const replyTo=(b.content_attributes||{}).in_reply_to||null;
    await r.set('msg:'+msgId,JSON.stringify({
      w:isIncoming?'c':'s',
      t:text.slice(0,300),
      a:attachments.map(a=>chatwootFileType(a.file_type)),
      r:replyTo?String(replyTo):null
    }),'EX',86400);
  }

  if(isOutgoing){
    const sender=b.sender||{};
    if((sender.type==='user'||sender.type==='agent')&&sender.id!==CFG.BOT_SENDER_ID){
      await S.update(r,key,st=>{
        st.state='HANDED_OFF';
        st.handedOffAt=Date.now();
        st.handoffReason=st.handoffReason||'human_replied';
        st.botDisabledPermanently=true;
        st.conversationId=convId;
        st.accountId=accountId;
        st.baseUrl=CFG.BASE_URL;
        return st;
      });
      console.log(`[Gate] Human replied — bot permanently disabled for ${key}`);
    }
    return null;
  }

  if(!isIncoming)return null;
  if((b.sender||{}).type==='agent_bot')return null;

  if(msgId){
    const ok=await r.set('dd:event:'+accountId+':'+convId+':'+msgId,'1','EX',2592000,'NX');
    if(ok!=='OK')return null;
  }

  const windowSec = CFG.DEDUP_WINDOW_SEC || 3600;
  const nowSec = Math.floor(now / 1000);

  if (identityKey && inboxId) {
    const phoneInboxKey = `pi:${identityKey}`;
    const lastRaw = await r.get(phoneInboxKey);
    let last = null;
    try { last = lastRaw ? JSON.parse(lastRaw) : null; } catch (e) {}

    const DUPLICATE_MSG = 'يبدو إنك بتكلمنا من رقم تاني، فردينا عليك هناك.\n\nهنقفل المحادثة دي عشان متشوفش ردود مكررة.\n\nلو محتاج حاجة تانية، كلمنا من الرقم الأساسي وهنساعدك فوراً.';

    if (last && String(last.inboxId) !== String(inboxId)) {
      const elapsedSec = nowSec - (last.atSec || 0);
      if (elapsedSec < windowSec) {
        console.log(`[Gate] Cross-inbox duplicate: identity=${identityKey} inbox=${inboxId} orig=${last.inboxId} elapsed=${elapsedSec}s`);
        await postPublicMessage(accountId, convId, DUPLICATE_MSG);
        await resolveConversation(accountId, convId);
        await r.set(phoneInboxKey, JSON.stringify({
          inboxId: String(inboxId),
          convId: String(convId),
          atSec: nowSec,
          duplicate: true
        }), 'EX', windowSec);
        return null;
      }
    }

    await r.set(phoneInboxKey, JSON.stringify({
      inboxId: String(inboxId),
      convId: String(convId),
      atSec: nowSec,
      duplicate: false
    }), 'EX', windowSec);
  }

  if(!text&&!attachments.length)return null;

  const hasAttachments=attachments.length>0;
  let attachmentType='NONE';
  if(hasAttachments){
    const types=attachments.map(a=>chatwootFileType(a.file_type));
    if(types.some(t=>t==='sticker'))attachmentType='STICKER';
    else if(types.some(t=>t==='audio'))attachmentType='AUDIO';
    else if(types.some(t=>t==='video'))attachmentType='VIDEO';
    else attachmentType='MEDIA';
  }

  if(attachmentType==='STICKER'){
    console.log(`[Gate] Sticker dropped (msgId=${msgId})`);
    return null;
  }

  const hasText=text.length>0;
  const hasLink=/https?:\/\/[^\s]+/.test(text);
  let truncated=false;
  if(text.length>CFG.MAX_LEN){text=text.slice(0,CFG.MAX_LEN);truncated=true;}
  let chatInput=text;
  if(truncated)chatInput+='\n\n(ملحوظة نظام: الرسالة مقطوعة)';

  const senderPhone=String((b.sender||{}).phone_number||((conv.meta||{}).sender||{}).phone_number||'');

  let replyNote='';
  const rid=(b.content_attributes||{}).in_reply_to;
  if(rid){
    let rep=null;
    const raw=await r.get('msg:'+rid);
    if(raw){try{rep=JSON.parse(raw);}catch(e){}}
    if(rep){
      const who=rep.w==='c'?'العميل نفسه':'المطبعة';
      const att=(rep.a||[]).length?' [مرفق: '+rep.a.join('، ')+']':'';
      replyNote='[العميل بيرد على رسالة من '+who+': "'+String(rep.t||'').slice(0,200)+'"'+att+']';
    }else{
      replyNote='[العميل بيرد على رسالة سابقة نصها غير متاح.]';
    }
  }

  let cleared=false;
  const st=await S.update(r,key,cur=>{
    if(cur.conversationId&&String(cur.conversationId)!==convId&&cur.state!=='COLLECTING_ORDER'){
      cur=S.fresh();cleared=true;
    }
    cur.conversationId=convId;
    cur.accountId=accountId;
    cur.baseUrl=CFG.BASE_URL;
    if(senderPhone)cur.contactPhone=senderPhone;
    if(senderPhoneStored){
      cur.customer=cur.customer||{name:null,phone:null,whatsappPhone:null,whatsappUsername:null};
      cur.customer.whatsappPhone=senderPhoneStored;
      if(!cur.customer.phone && !(cur.partialOrder&&cur.partialOrder.phone)){
        cur.customer.phone=senderPhoneStored;
      }
    }
    if(waUsername){
      cur.customer=cur.customer||{name:null,phone:null,whatsappPhone:null,whatsappUsername:null};
      cur.customer.whatsappUsername=waUsername;
    }
    cur.lastCustomerAt=now;
    if(cur.state==='HANDED_OFF')return cur;

    cur.recentClientMessages=cur.recentClientMessages||[];
    if(hasText){
      const lastMsg=cur.recentClientMessages[cur.recentClientMessages.length-1];
      if(lastMsg!==text.slice(0,200)){
        cur.recentClientMessages.push(text.slice(0,200));
        if(cur.recentClientMessages.length>5)cur.recentClientMessages.shift();
      }
    }
    if(hasAttachments&&!hasText){
      const marker=attachmentType==='AUDIO'?'[رسالة صوتية]':
                   attachmentType==='VIDEO'?'[فيديو]':
                   attachmentType==='MEDIA'?'[ملف/صورة]':'[مرفق]';
      cur.recentClientMessages.push(marker);
      if(cur.recentClientMessages.length>5)cur.recentClientMessages.shift();
    }
    cur.recentClientMessagesAt=now;

    if(attachments.some(a=>a&&(a.file_url||a.data_url))){
      cur.media=cur.media||{urls:[],count:0};
      let pushed=0;
      for(const att of attachments){
        const url=att.file_url||att.data_url||'';
        if(!url)continue;
        const name=att.file_name||att.file_url?.split('?')[0].split('/').pop()||'ملف';
        const size=att.file_size||0;
        if(cur.media.urls.some(m=>String(m.msgId)===msgId && m.url===url))continue;
        cur.media.urls.push({
          url,
          name,
          type: resolveMediaType(att),
          source:'customer',
          sentAt:now,
          msgId,
          analyzed:null,
          notes:'',
          file_size:size,
          chatwoot_file_type: Number(att.file_type) || 0,
          conversationId: cur.conversationId || cId
        });
        pushed++;
      }
      if(pushed>0){
        cur.media.count=(cur.media.count||0)+pushed;
        cur.media.lastMediaAt=now;
      }
    }

    if(attachmentType==='AUDIO'){
      cur.pendingAudioUrl=attachments.map(a=>a.file_url||a.data_url||'').filter(Boolean)[0]||'';
    }

    if(hasLink){
      const SKIP_URLS=['maps.app.goo.gl','example.com/upload/'];
      const urlMatches=text.match(/https?:\/\/[^\s]+/g)||[];
      cur.media=cur.media||{urls:[],count:0};
      for(const url of urlMatches){
        if(SKIP_URLS.some(s=>url.includes(s)))continue;
        const base=url.split('?')[0];
        if(cur.media.urls.some(m=>m.url&&m.url.split('?')[0]===base))continue;
        let host='';
        try{host=new URL(url).hostname;}catch(e){}
        cur.media.urls.push({
          url,
          name:base.split('/').pop()||url,
          type:'link',
          source:'customer',
          host,
          sentAt:now,msgId,
          analyzed:null,notes:'',
          file_size:0
        });
        cur.media.count=(cur.media.count||0)+1;
        cur.media.lastMediaAt=now;
      }
    }

    if(hasText){
      cur.partialOrder=cur.partialOrder||{};
      cur.partialOrder.lastDetailText=text.slice(0,500);
      cur.partialOrder.lastDetailAt=now;
      cur.partialOrder.updatedAt=now;
    }

    if(rid){
      const urls=(cur.media&&cur.media.urls)||[];
      const target=urls.find(m=>m.msgId===String(rid));
      if(target){
        cur.replyToMedia={msgId:String(rid),url:target.url,name:target.name,type:target.type};
      } else {
        cur.replyToMedia=null;
      }
    }

    return cur;
  });

  if(cleared)await S.clearChat(r,key);
  if(st.state==='HANDED_OFF')return null;

  if(isIncoming&&!hasAttachments&&hasText){
    await S.run(async r=>{
      let cursor=rid?String(rid):null;
      let mediaMsgId=null;
      let hops=0;
      const MAX_HOPS=15;
      while(cursor&&hops<MAX_HOPS){
        const st0=await S.get(r,key)||{};
        const hit=((st0.media&&st0.media.urls)||[]).find(m=>String(m.msgId)===cursor);
        if(hit){mediaMsgId=cursor;break;}
        const raw=await r.get('msg:'+cursor);
        if(!raw)break;
        let parsed=null;
        try{parsed=JSON.parse(raw);}catch(e){}
        if(!parsed||!parsed.r)break;
        cursor=String(parsed.r);
        hops++;
      }
      if(!mediaMsgId)return;
      await S.update(r,key,cur=>{
        const urls=(cur.media&&cur.media.urls)||[];
        const target=urls.find(m=>String(m.msgId)===String(mediaMsgId));
        if(target){
          const prior=target.notes?target.notes+'\n':'';
          target.notes=(prior+text).slice(0,800);
        }
        return cur;
      });
    });
  }

  return {
    chatInput,rawText:text,attachmentType,attachments,hasText,hasAttachments,hasLink,
    convState:st,contactKey:key,sessionId:'chat:'+key,replyNote,
    rid:rid?String(rid):null,
    replyToMedia:st.replyToMedia||null,
    inboxId,
    senderPhone:senderPhoneStored,
    waUsername,
    identityKey,
    accountId,conversationId:convId,baseUrl:CFG.BASE_URL,
    rateLimited:false,messageId:msgId
  };
});
return out?[{json:out}]:[];

const S = require('/files/bot_state_v2.js');
const now = Date.now();
const HANDOFF_AFTER_MS = 60 * 60 * 1000;
const AUTO_RESOLVE_AFTER_MS = 3 * 60 * 60 * 1000;

const NUDGEABLE_STATES = ['NORMAL', 'COLLECTING_ORDER'];

// ═══════════════════════════════════════════════════════════════
// ── MEDIA BUNDLER (ZIP) ──
// ═══════════════════════════════════════════════════════════════
const BUNDLER_URL = 'http://media-bundler:3000';
const BUNDLER_TOKEN = 'REPLACE_WITH_YOUR_SECRET';

async function bundleMedia(helpers, mediaUrls, gate) {
  if (!mediaUrls || mediaUrls.length < 2) {
    return { ok: false, reason: 'too_few_files' };
  }
  const files = mediaUrls.map(f => ({
    url: f.url,
    name: f.name || 'file',
    notes: f.notes || '',
    copies: f.copies || null,
    printType: f.printType || null
  }));
  try {
    const resp = await helpers.httpRequest({
      method: 'POST',
      url: `${BUNDLER_URL}/bundle`,
      headers: {
        'Content-Type': 'application/json',
        'X-Internal-Token': BUNDLER_TOKEN
      },
      body: {
        contactKey: gate.contactKey,
        conversationId: gate.conversationId,
        accountId: gate.accountId,
        files,
        options: { preserveDuplicates: true }
      },
      json: true,
      timeout: 300000
    });
    return resp;
  } catch (e) {
    console.error(`[bundleMedia] failed: ${e.message}`);
    return { ok: false, reason: 'service_error', error: String(e.message) };
  }
}

const items = await S.run(async r => {
  const keys = [];
  let cursor = '0';
  do {
    const [nextCursor, batch] = await r.scan(cursor, 'MATCH', 'ct:*', 'COUNT', 100);
    cursor = nextCursor;
    keys.push(...batch);
  } while (cursor !== '0');

  const results = [];

  for (const fullKey of keys) {
    const raw = await r.get(fullKey);
    if (!raw) continue;
    let st;
    try { st = JSON.parse(raw); } catch (e) { continue; }

    const key = fullKey.replace(/^ct:/, '');
    const state = st.state || 'NORMAL';

    if (st.botDisabledPermanently) continue;

    const accountId = st.accountId;
    const baseUrl = st.baseUrl || 'http://chatwoot-rails-1:3000';
    const convId = st.conversationId;
    if (!accountId || !convId) continue;

    const lastCustomer = st.lastCustomerAt || 0;
    if (lastCustomer === 0) continue;

    const lastBot = st.lastBotAt || 0;
    const sinceCustomer = now - lastCustomer;

    const order = st.confirmedOrder || null;
    const partial = st.partialOrder || {};
    const media = st.media || { urls: [], count: 0 };
    const mediaUrls = media.urls || [];
    const inquiry = st.inquiry || {};
    const hasOrder = !!(order || partial.orderDetails || partial.name);

    // ═══════════════════════════════════════════════════
    // PATH 1: AUTO-RESOLVE (3h)
    // ═══════════════════════════════════════════════════
    if (state === 'NORMAL' && !hasOrder && sinceCustomer >= AUTO_RESOLVE_AFTER_MS) {
      if (lastBot > lastCustomer) {
        console.log(`[cron] auto-resolve ${key} (silent ${Math.round(sinceCustomer/60000)}min)`);

        const lockKey = `actionlock:autoresolve:${key}`;
        const gotLock = await S.run(r2 => r2.set(lockKey, '1', 'EX', 300, 'NX'));

        if (gotLock === 'OK') {
          await S.run(async r2 => {
            const push = async (payload) => {
              await r2.rpush('pending_actions', JSON.stringify({
                ...payload,
                baseUrl, accountId, conversationId: convId,
                at: now, retries: 0
              }));
            };
            await push({ action: 'set_label', label: 'استفسار' });
            await push({ action: 'toggle_status', status: 'resolved' });
          });
        } else {
          console.log(`[cron] auto-resolve already queued for ${key} — skipping`);
        }

        await S.update(r, key, s => {
          s.state = 'RESOLVED';
          s.resolvedAt = now;
          s.botDisabledPermanently = true;
          return s;
        });

        await S.run(r => S.logEvent(r, key, 'conversation_resolved', {
          reason: 'silent_auto_resolve',
          silent_minutes: Math.round(sinceCustomer / 60000)
        }));

        results.push({
          json: {
            type: 'AUTO_RESOLVE',
            contactKey: key,
            convId, accountId, baseUrl,
            label: 'استفسار'
          }
        });
        continue;
      }
    }

    // ═══════════════════════════════════════════════════
    // PATH 2: SILENT HANDOFF (60 min)
    // ═══════════════════════════════════════════════════
    if (!NUDGEABLE_STATES.includes(state)) continue;

    const nudgeCount = st.nudgeCount || 0;
    if (nudgeCount >= 2) continue;

    if (sinceCustomer < HANDOFF_AFTER_MS) continue;

    const label = hasOrder ? 'طلب_طباعة' : 'استفسار';

    let summary = '⏰ تحويل تلقائي (العميل لم يرد لأكثر من ساعة)\n\n';
    summary += 'السبب: no_reply_60min\n\n';

    if (order) {
      summary += '📋 طلب مؤكد:\n';
      summary += '🔑 OrderID: ' + (order.orderId || '—') + '  (internal)\n';
      summary += 'الاسم: ' + (order.name || '—') + '\n';
      summary += 'رقم التواصل: ' + (order.phone || '—') + '\n';
      summary += 'الطلب: ' + (order.order || '—') + '\n';
      if (order.notes && order.notes !== 'لا يوجد') summary += 'ملاحظات: ' + order.notes + '\n';
      summary += 'ملفات مستلمة: ' + (media.count || 0) + '\n';
    } else if (partial.name || partial.orderDetails) {
      summary += '📋 بيانات مجمعة (الطلب لسه ما اتأكدش):\n';
      if (partial.name) summary += 'الاسم: ' + partial.name + '\n';
      if (partial.phone) summary += 'رقم التواصل: ' + partial.phone + '\n';
      if (partial.orderDetails) summary += 'الطلب: ' + partial.orderDetails + '\n';
      summary += 'ملفات مستلمة: ' + (media.count || 0) + '\n';
    } else {
      summary += 'العميل كان يستفسر ولم يكمل.\n';
      if (inquiry.topic) summary += 'الاستفسار كان عن: ' + inquiry.topic + '\n';
    }

    // ── Try to ZIP the media (fallback to URLs if it fails) ──
    if (mediaUrls.length > 0) {
      const bundle = await bundleMedia(this.helpers, mediaUrls, {
        contactKey: key,
        conversationId: convId,
        accountId
      });

      if (bundle.ok) {
        summary += `\n📎 الملفات (${mediaUrls.length}) — مرفقة كـ ZIP:\n`;
        summary += bundle.zipUrl + '\n';
        summary += '\nالملفات جوه الـ ZIP:\n';
        bundle.manifest.forEach(m => {
          summary += `- ${m.final}\n`;
        });
        if (bundle.skipped && bundle.skipped.length > 0) {
          summary += '\n⚠️ ملفات اتحطت كـ لينك (فشل التحميل):\n';
          bundle.skipped.forEach(s => {
            summary += `- ${s.name}: ${s.url}  (${s.reason})\n`;
          });
        }
      } else {
        summary += '\n📎 الملفات (' + mediaUrls.length + '):\n';
        mediaUrls.forEach(f => {
          summary += `- ${f.name} (${f.type}): ${f.url}\n`;
        });
      }
    }

    summary += '\nيحتاج متابعة من الفريق.';

    // ── Idempotency lock ──
    const lockKey = `actionlock:silenthandoff:${key}`;
    const gotLock = await S.run(r2 => r2.set(lockKey, '1', 'EX', 300, 'NX'));

    if (gotLock === 'OK') {
      await S.run(async r2 => {
        const push = async (payload) => {
          await r2.rpush('pending_actions', JSON.stringify({
            ...payload,
            baseUrl, accountId, conversationId: convId,
            at: now, retries: 0
          }));
        };
        await push({ action: 'post_note', content: summary });
        await push({ action: 'set_label', label });
        await push({ action: 'toggle_status', status: 'open' });
      });
    } else {
      console.log(`[cron] silent handoff already queued for ${key} — skipping`);
    }

    await S.update(r, key, s => {
      s.nudgeCount = 2;
      s.lastNudgeAt = now;
      s.state = 'HANDED_OFF';
      s.handoffReason = 'no_reply_60min';
      s.handedOffAt = now;
      s.botDisabledPermanently = true;
      return s;
    });

    await S.run(r => S.logEvent(r, key, 'handoff', { reason: 'no_reply_60min', source: 'cron' }));

    results.push({
      json: {
        type: 'SILENT_HANDOFF',
        contactKey: key,
        convId, accountId, baseUrl,
        label,
        hasOrder
      }
    });
  }

  return results;
});

return items.length ? items : [];

