// ─────────────────────────────────────────────────────────
// Tunables — cap sizes to prevent unbounded growth
// ─────────────────────────────────────────────────────────
const MAX_MEDIA_SHOWN = Math.max(5, (gate.batchMessageIds || []).length, (gate.attachments || []).length);        // show last N media items
const MAX_EVENTS_SHOWN = 3;       // show last N events
const MAX_DESIGN_NOTES_SHOWN = 5; // show last N design notes
const MAX_OLDER_MEDIA_HINT = 20;  // max "older" items to still advertise

// ─────────────────────────────────────────────────────────
// Fresh state (source of truth)
// ─────────────────────────────────────────────────────────
const freshState = (await S.run(r => S.get(r, gate.contactKey))) || {};
const state = { ...(gate.convState || {}), ...freshState };
if (state.botDisabledPermanently || state.state === 'HANDED_OFF') return [];
const greetings = /^(?:السلام عليكم(?: ورحمة الله(?: وبركاته)?)?|وعليكم السلام|سلام عليكم|اهلا|أهلا|اهلاً|أهلاً|مرحبا|مرحباً|هاي|هالو|hello|hi|صباح الخير|مساء الخير)$/i;
const inputLines=String(it.transcribedText || it.rawText || '').split(/\n+/).map(s=>s.replace(/[.!؟?،,]/g,'').trim()).filter(Boolean);
if (!it.hasAttachments && !it.hasLink && inputLines.length && inputLines.every(s=>greetings.test(s))) return [];

const convState = state.state || 'NORMAL';
const confirmedOrder = state.confirmedOrder || null;
const partialOrder = state.partialOrder || {};
const inquiry = state.inquiry || {};
const feedback = state.feedback || {};
const media = state.media || { urls: [], count: 0 };
const mediaUrls = media.urls || [];
const mediaCount = media.count || 0;
const customer = state.customer || {};
