// Media section — LAST N ONLY + explicit "older" hint
// ─────────────────────────────────────────────────────────
let mediaSection = '';
const ids=(mediaUrls.map(f=>String(f.msgId||''))).filter(Boolean);
const repeatedIds=[...new Set(ids.filter((id,i)=>ids.indexOf(id)!==i))];
if (mediaUrls.length > 0) {
  const total = mediaUrls.length;
  const firstBatchMedia = mediaUrls.findIndex(f=>(gate.batchMessageIds||[]).includes(String(f.msgId)));
  const startIdx = firstBatchMedia >= 0 ? Math.min(firstBatchMedia,Math.max(0,total-MAX_MEDIA_SHOWN)) : Math.max(0,total-MAX_MEDIA_SHOWN);
  const recent = mediaUrls.slice(startIdx);
  const olderCount = startIdx;

  const lines = recent.map((f, i) => {
    const idx = startIdx + i + 1;   // 1-based position in full list
    const siblingIndex = mediaUrls.slice(0,startIdx+i).filter(m=>String(m.msgId)===String(f.msgId)).length;
    const msgTag = f.msgId ? `[msg_${f.msgId}] [att_${siblingIndex}]` : '[no msgId]';
    const type = f.type || 'file';
    const source = f.source === 'internal_note' ? 'agent-note' : 'customer';

    // ── Cache marker: unmistakable ──
    let analyzed;
    if (f.analyzed && !f.analyzed.error && f.analyzed.ok !== false) {
      const parts = [];
      const evidence={};
      for(const k of ['description','visual_keywords','likely_print_service','is_transfer_receipt','transfer_provider','payment_provider','transfer_amount','require_handoff','requires_upload']) if(f.analyzed[k]!=null) evidence[k]=f.analyzed[k];
      parts.push(JSON.stringify(evidence));
      if (f.analyzed.type) parts.push(`type=${f.analyzed.type}`);
      if (f.analyzed.pages)  parts.push(`pages=${f.analyzed.pages}`);
      if (f.analyzed.slides) parts.push(`slides=${f.analyzed.slides}`);
      if (f.analyzed.sheets) parts.push(`sheets=${f.analyzed.sheets}`);
      if (f.analyzed.likely_print_service && f.analyzed.likely_print_service !== 'غير محدد') {
        parts.push(f.analyzed.likely_print_service);
      }
      analyzed = ` ✅ CACHED ${parts.join(' ')} — DO NOT re-analyze`;
    } else {
      analyzed = f.analyzed?.error ? ' ⚠ Analysis failed; never treat as verified: '+f.analyzed.error : ' ⬜ NOT analyzed';
    }

    const notePart = f.notes ? ` — customer note: "${String(f.notes).slice(0, 100)}"` : '';
    return `${idx}. ${msgTag} ${type} [${source}] ${f.name || 'file'}${analyzed}${notePart}`;
  }).join('\n');

  const olderHint = olderCount > 0
    ? `\n(+${olderCount} older file${olderCount === 1 ? '' : 's'} still stored — call analyze_media(msg_id) if needed)`
    : '';

  mediaSection = `\n\n[📎 Media (${total} total, showing last ${recent.length}):\n${lines}${olderHint}]`;
} else if (mediaCount > 0) {
  mediaSection = `\n\n[📎 Media count: ${mediaCount}. Details unavailable.]`;
}

// ─────────────────────────────────────────────────────────
