}

if (convState === 'COLLECTING_ORDER') {
  stateNote += `\n\n[You are mid-order. The customer's real WhatsApp number is: ${contactPhone}. Save every new piece of data via record_order_progress immediately.]`;
} else if (convState === 'ORDER_CONFIRMED') {
  const orderName = confirmedOrder?.name || '?';
  const orderPhone = confirmedOrder?.phone || '?';
  const orderText = confirmedOrder?.order || '?';
  stateNote += `\n\n[Order confirmed. Name=${orderName}, Phone=${orderPhone}, Order=${orderText}. Media received: ${mediaUrls.length}. Order already finalized; do not finalize or hand off again.]`;
} else if (convState === 'HANDED_OFF') {
  stateNote += `\n\n[This conversation is HANDED_OFF — a human agent is handling it. Do not respond on the bot's behalf.]`;
}

// ─────────────────────────────────────────────────────────
// Partial order — cap design notes to last N
// ─────────────────────────────────────────────────────────
const partialEntries = [];
if (partialOrder.name) partialEntries.push(`name: ${partialOrder.name}`);
if (partialOrder.phone) partialEntries.push(`phone: ${partialOrder.phone}`);
if (partialOrder.orderDetails) partialEntries.push(`order: ${partialOrder.orderDetails}`);
if (partialOrder.expectedFileCount) partialEntries.push(`expected_files: ${partialOrder.expectedFileCount}`);
if (partialOrder.dimensions?.wCm && partialOrder.dimensions?.hCm) {
  partialEntries.push(`dimensions: ${partialOrder.dimensions.wCm}×${partialOrder.dimensions.hCm} cm`);
}

// Design notes — last N only + count of the rest
if (Array.isArray(partialOrder.designNotes) && partialOrder.designNotes.length > 0) {
  const allNotes = partialOrder.designNotes;
  const shown = allNotes.slice(-MAX_DESIGN_NOTES_SHOWN);
  const olderNotes = allNotes.length - shown.length;
  const startIdx = Math.max(0, allNotes.length - MAX_DESIGN_NOTES_SHOWN);

  const notesText = shown.map((n, i) => `  ${startIdx + i + 1}. "${n.text}"`).join('\n');
  const olderHint = olderNotes > 0
    ? `\n  (+${olderNotes} older note${olderNotes === 1 ? '' : 's'} — full list preserved in state and shown in finalize_order)`
    : '';

  partialEntries.push(`design_notes:\n${notesText}${olderHint}`);
}

if (partialEntries.length > 0) {
  stateNote += `\n\n[Already collected (do NOT re-ask): ${partialEntries.join(' | ')}]`;
}

// ─────────────────────────────────────────────────────────
// Inquiry context
// ─────────────────────────────────────────────────────────
if (inquiry.topic || (inquiry.askedAbout || []).length > 0) {
  const topics = (inquiry.askedAbout || []).join(', ');
  const prices = (inquiry.quotedPrices || []).map(p => `${p.item}: ${p.price}`).join(' | ');
  stateNote += `\n\n[Inquiry: topic="${inquiry.topic || topics}". Already quoted: ${prices || 'none'}.]`;
}

// ─────────────────────────────────────────────────────────
// Recent events — LAST N ONLY
// ─────────────────────────────────────────────────────────
let eventsSection = '';
const events = await S.run(r => S.getEvents(r, gate.contactKey, MAX_EVENTS_SHOWN));
if (events.length > 0) {
  const lines = events.map(e => {
    const ago = Math.round((Date.now() - e.at) / 1000);
    const t = ago < 60 ? `${ago}s ago` : `${Math.round(ago / 60)}m ago`;
    const dataStr = e.data && Object.keys(e.data).length > 0
      ? ' ' + JSON.stringify(e.data).slice(0, 120)
      : '';
    return `- ${t}: ${e.type}${dataStr}`;
  }).join('\n');
  eventsSection = `\n\n[Recent events (last ${events.length}):\n${lines}]`;
}

// ─────────────────────────────────────────────────────────
// Reply-to-media hint
// ─────────────────────────────────────────────────────────
if (gate.replyToMedia) {
  const m = gate.replyToMedia;
  stateNote += `\n\n[🔍 Customer is replying to [msg_${m.msgId}]: ${m.name} (${m.type}). Call analyze_media(msg_id="${m.msgId}") to understand what they want with it.]`;
} else if (gate.rid) {
  stateNote += `\n\n[Customer is replying to an earlier message (id: ${gate.rid}).]`;
}

// ─────────────────────────────────────────────────────────
// Video
// ─────────────────────────────────────────────────────────
const currentClientMedia = mediaUrls.filter(m => m && m.source === 'customer' && String(m.msgId) === String(gate.msgId || ''));
const currentMediaTypes = [...new Set(currentClientMedia.map(m => m.type || 'file'))];
if (currentClientMedia.length > 0) {
  const supported = new Set(['image','video','pdf','doc','text','archive','sticker']);
  const analyzable = currentClientMedia.map((media, index) => ({ media, index })).filter(item => supported.has(item.media.type || 'file'));
  const msgId = String(currentClientMedia[0].msgId);
  const calls = analyzable.map(item => `analyze_media(msg_id="${msgId}", attachment_index=${item.index})`).join('; ');
  if (calls) stateNote += `\n\n[Customer attached ${currentClientMedia.length} file(s) (${currentMediaTypes.join(', ')}). The original attachments are archived independently of analysis. If the customer refers to their contents, try these supported analyzers first: ${calls}. Do not say image/video files cannot be opened before attempting analysis. Audio uses the existing Whisper transcription path.]`;
}

// ─────────────────────────────────────────────────────────
// Upload link — conditional injection only
// ─────────────────────────────────────────────────────────
const uploadLink = `https://example.com/upload/${gate.conversationId || ''}`;

// Inject when:
//   1. There's a pending internal media (agent uploaded via note), OR
//   2. Customer sent a video (they might send more), OR
//   3. There's a pending audio (rare), OR
//   4. The last media item's analysis returned requires_upload
const lastMedia = mediaUrls[mediaUrls.length - 1];
const lastAnalysisRequiresUpload = !!(lastMedia && lastMedia.analyzed && lastMedia.analyzed.requires_upload);

const shouldInjectUploadLink =
  lastAnalysisRequiresUpload || /(?:ارفع|رفع|upload|100\s*mb)/i.test(base);

if (shouldInjectUploadLink) {
  stateNote += `\n\n[Upload link (share only if customer has more files >100MB): ${uploadLink}]`;
}

// ─────────────────────────────────────────────────────────
// Final assembled prompt
// ─────────────────────────────────────────────────────────
return [{
  json: {
    ...it,
    chatInput: base + mediaSection + pendingInternalSection + stateNote + eventsSection
  }
}];

const fs = require('fs');

// ─────────────────────────────────────────────────────────
// Load structured price catalog
// ─────────────────────────────────────────────────────────
let catalog;
try {
