// ─────────────────────────────────────────────────────────
// Parse inputs (query string OR structured object)
// ─────────────────────────────────────────────────────────
const input = typeof query === 'string' ? { query } : (query || {});
const rawQuery = String(input.query || input.text || '').trim();

// Structured filters (AI can pass these directly)
const fCategory    = String(input.category || '').trim();
const fSubcategory = String(input.subcategory || '').trim();
const fProduct     = String(input.product || '').trim();
const fMaterial    = String(input.material || '').trim();
const fFinish      = String(input.finish || '').trim();
const fSize        = String(input.size || '').trim();
const fGrammage    = input.grammage != null ? Number(input.grammage) : null;
const fMaxPrice    = input.max_price != null ? Number(input.max_price) : null;
const fMinPrice    = input.min_price != null ? Number(input.min_price) : null;

// ─────────────────────────────────────────────────────────
// Arabic normalization
// ─────────────────────────────────────────────────────────
function normalizeAr(s) {
  return String(s || '')
    .toLowerCase()
    .replace(/[\u064b-\u065f\u0670\u0640]/g, '')
    .replace(/[\u0623\u0625\u0622]/g, '\u0627')
    .replace(/\u0649/g, '\u064a')
    .replace(/\u0629/g, '\u0647')
    .replace(/\s+/g, ' ')
    .trim();
}

// ─────────────────────────────────────────────────────────
// Synonyms + product mapping
// ─────────────────────────────────────────────────────────
const SYNONYMS = {
  'كارت': 'كروت شخصيه', 'كروت': 'كروت شخصيه', 'كرت': 'كروت شخصيه',
  'business card': 'كروت شخصيه', 'بزنس كارد': 'كروت شخصيه',
  'ستيكر': 'استيكر', 'sticker': 'استيكر', 'ملصق': 'استيكر',
  'لافته': 'بانر اوت دور', 'لافتة': 'بانر اوت دور', 'بنر': 'بانر اوت دور',
  'اوت دور': 'بانر اوت دور', 'outdoor': 'بانر اوت دور',
  'كانفاس': 'كانفس', 'canvas': 'كانفس',
  'تيشيرت': 'تيشرتات', 'تشيرت': 'تيشرتات', 'tshirt': 'تيشرتات',
  'مج': 'مج', 'بينز': 'بينز',
  'ظرف': 'اظرف', 'ظروف': 'اظرف', 'envelope': 'اظرف',
  'فولدر': 'فولدر', 'مجلد': 'فولدر',
  'فلاير': 'فلايرات', 'flyer': 'فلايرات',
  'سلفان': 'سلوفان',
  'تجليد': 'تجليد', 'تكعيب': 'تكعيب',
  'دبوس': 'تدبيس', 'staple': 'تدبيس',
  'قص': 'برنت كت', 'cut': 'برنت كت',
  'رول اب': 'رول اب', 'استاند': 'رول اب',
  'pvc': 'كروت PVC', 'بلاستيك': 'كروت PVC',
  'اسكانر': 'اسكانر', 'سكانر': 'اسكانر', 'scan': 'اسكانر',
  'هندسي': 'لوحات هندسيه', 'هندسيه': 'لوحات هندسيه',
  'ورق شركه': 'ورق الشركة', 'ورق شركة': 'ورق الشركة',
  'فوم': 'فوم', 'foam': 'فوم',
  'كانسون': 'كانسون',
};

// ─────────────────────────────────────────────────────────
// Expand tokens with synonyms
// ─────────────────────────────────────────────────────────
function expandTokens(q) {
  const norm = normalizeAr(q);
  const tokens = norm.split(/[\s,،\/\-\(\)\.]+/).filter(Boolean);
  const expanded = new Set(tokens);
  for (const t of tokens) {
    if (SYNONYMS[t]) {
      normalizeAr(SYNONYMS[t]).split(/\s+/).forEach(w => expanded.add(w));
    }
  }
  return [...expanded].filter(w => w.length > 1);
}

// ─────────────────────────────────────────────────────────
// Extract structured intent from the query
// ─────────────────────────────────────────────────────────
function extractIntent(q) {
  const norm = normalizeAr(q);
  const it = {};

  // Grammage: "350 جرام", "200g"
  const gMatch = norm.match(/(\d{2,4})\s*(?:جرام|g|gram|gsm)/);
  if (gMatch) it.grammage = Number(gMatch[1]);

  // Size: A4, A3, ربع فرخ, نص فرخ, فرخ كامل, 120×80
  const sizeMatch = q.match(/\b(A[0-5]|ربع\s*فرخ|نص\s*فرخ|فرخ\s*كامل|\d+\s*[×xX]\s*\d+)\b/i);
  if (sizeMatch) it.size = sizeMatch[1].replace(/\s+/g, ' ');

  // Finish keywords
  if (/\bلامع\b/.test(norm)) it.finish = 'لامع';
  else if (/\bمط\b|مطفي/.test(norm)) it.finish = 'مط';
  else if (/\bسلوفان\b/.test(norm)) it.finish = 'سلوفان';
  else if (/برنت\s*كت/.test(norm)) it.finish = 'برنت كت';
  else if (/بدون\s*سلوفان/.test(norm)) it.finish = 'بدون سلوفان';

  // Material
  if (/كوشيه/.test(norm)) it.material = 'كوشيه';
  else if (/بريستول/.test(norm)) it.material = 'بريستول';
  else if (/بلاستيك/.test(norm)) it.material = 'بلاستيك';
  else if (/\bشفاف\b/.test(norm)) it.material = 'شفاف';
  else if (/ذهب/.test(norm)) it.material = 'ذهبي';
  else if (/سيلفر|فضي|هولوجرام|مصنفر/.test(norm)) it.material = 'سيلفر';
  else if (/ورق/.test(norm)) it.material = 'ورق';

  // Product
  if (/كارت|كروت|كرت/.test(norm)) it.product = 'كروت شخصيه';
  else if (/ستيكر|sticker/.test(norm)) it.product = 'استيكر';
  else if (/بانر|لافتة|اوت دور/.test(norm)) it.product = 'بانر اوت دور';
  else if (/رول\s*اب|استاند/.test(norm)) it.product = 'رول اب';
  else if (/فلاير|flyer/.test(norm)) it.product = 'فلايرات';
  else if (/ظرف|ظروف/.test(norm)) it.product = 'اظرف';
  else if (/فولدر|مجلد/.test(norm)) it.product = 'فولدر';
  else if (/تيشرت|تشيرت/.test(norm)) it.product = 'تيشرتات';
  else if (/\bمج\b/.test(norm)) it.product = 'مج';
  else if (/فوم|foam/.test(norm)) it.product = 'فوم';
  else if (/كانفس|كانفاس/.test(norm)) it.product = 'كانفس';
  else if (/فينيل/.test(norm)) it.product = 'فينيل';
  else if (/سي\s*ثرو/.test(norm)) it.product = 'سي ثرو';
  else if (/pvc/.test(norm)) it.product = 'كروت PVC';
  else if (/اسكانر|سكانر/.test(norm)) it.product = 'اسكانر';
  else if (/هندس/.test(norm)) it.product = 'لوحات هندسيه';
  else if (/تدبيس|بوكليت/.test(norm)) it.product = 'تدبيس';
  else if (/تجليد|تكعيب/.test(norm)) it.product = 'تكعيب';
  else if (/ورق\s*شرك/.test(norm)) it.product = 'ورق الشركة';
  else if (/روول|رول اب|ستاند/.test(norm)) it.product = 'رول اب';

  return it;
}

const intent = extractIntent(rawQuery);

// Merge AI-provided filters (they take priority over inferred)
const merged = {
  category: fCategory || '',
  subcategory: fSubcategory || '',
  product: fProduct || intent.product || '',
  material: fMaterial || intent.material || '',
  finish: fFinish || intent.finish || '',
  size: fSize || intent.size || '',
  grammage: fGrammage != null ? fGrammage : (intent.grammage || null),
  max_price: fMaxPrice,
  min_price: fMinPrice,
};

const queryTokens = expandTokens(rawQuery);

// ─────────────────────────────────────────────────────────
// Detect generic question
// ─────────────────────────────────────────────────────────
const isGeneric = /كل الخدمات|قايمه|قائمه|قائمة|قايمة|ايه الخدمات|ايه اللي بتعملوه|بتعمل ايه|خدماتكم|خدمات المطبعه|كل حاجه|عندكم ايه|بتعملوا ايه/.test(normalizeAr(rawQuery));

if (isGeneric) {
  const cats = [...new Set(items.map(i => i.category).filter(Boolean))];
  return JSON.stringify({
    ok: true,
    found: true,
    generic: true,
    query: rawQuery,
    categories: cats,
  });
}

// ─────────────────────────────────────────────────────────
// Score items
// ─────────────────────────────────────────────────────────
function scoreItem(item) {
  let score = 0;
  const reasons = [];

  // Product filter (hard)
  if (merged.product) {
    const p = normalizeAr(item.product);
    const cat = normalizeAr(item.category);
    const sub = normalizeAr(item.subcategory);
    const wantP = normalizeAr(merged.product);
    const matchProduct = p.includes(wantP) || cat.includes(wantP) || sub.includes(wantP) ||
                         wantP.includes(p) || (p && wantP.includes(p));
    if (matchProduct) { score += 20; reasons.push('product'); }
    else { return { score: -1, reasons: ['product_mismatch'] }; }
  }

  // Material (hard)
  if (merged.material) {
    const m = normalizeAr(item.material);
    const n = normalizeAr(item.notes);
    const wantM = normalizeAr(merged.material);
    if (m.includes(wantM) || wantM.includes(m) || n.includes(wantM)) { score += 10; reasons.push('material'); }
    else { return { score: -1, reasons: ['material_mismatch'] }; }
  }

  // Grammage (hard)
  if (merged.grammage) {
    if (item.grammage === merged.grammage) { score += 15; reasons.push('grammage'); }
    else { return { score: -1, reasons: ['grammage_mismatch'] }; }
  }

  // Size (soft — boost if matches)
  if (merged.size) {
    const sz = normalizeAr(item.size);
    const wantSz = normalizeAr(merged.size);
    if (sz && (sz.includes(wantSz) || wantSz.includes(sz))) { score += 10; reasons.push('size'); }
  }

  // Finish (soft)
  if (merged.finish) {
    const f = normalizeAr(item.finish);
    const n = normalizeAr(item.notes);
    const wantF = normalizeAr(merged.finish);
    if (f.includes(wantF) || n.includes(wantF)) { score += 8; reasons.push('finish'); }
  }

  // Price range filter
  const effectivePrice = item.price_side_1 ?? item.price_flat ?? item.price_starting;
  if (merged.max_price != null && effectivePrice != null && effectivePrice > merged.max_price) {
    return { score: -1, reasons: ['above_max_price'] };
  }
  if (merged.min_price != null && effectivePrice != null && effectivePrice < merged.min_price) {
    return { score: -1, reasons: ['below_min_price'] };
  }

  // Token overlap on search_key
  const sk = item.search_key || normalizeAr(`${item.category} ${item.product} ${item.material} ${item.finish} ${item.size}`);
  for (const token of queryTokens) {
    if (sk.includes(token)) { score += 2; reasons.push(`token:${token}`); }
  }

  return { score, reasons };
}

const scored = items
  .map(item => { const r = scoreItem(item); return { item, score: r.score, reasons: r.reasons }; })
  .filter(x => x.score > 0)
  .sort((a, b) => b.score - a.score);

// ─────────────────────────────────────────────────────────
// Trim item for output
// ─────────────────────────────────────────────────────────
function trim(item) {
  return {
    id: item.id,
    category: item.category,
    subcategory: item.subcategory,
    product: item.product,
    size: item.size,
    material: item.material,
    grammage: item.grammage,
    finish: item.finish,
    side: item.side,
    prices: {
      side_1: item.price_side_1,
      side_2: item.price_side_2,
      flat: item.price_flat,
      starting: item.price_starting,
    },
    unit: item.unit,
    price_notes: item.price_notes,
    notes: item.notes,
  };
}

// ─────────────────────────────────────────────────────────
// Return top matches or near matches
// ─────────────────────────────────────────────────────────
const MAX_RESULTS = 10;
const top = scored.slice(0, MAX_RESULTS).map(x => trim(x.item));

if (top.length === 0) {
  // Loose fallback — token overlap only
  const loose = items
    .map(item => {
      const sk = item.search_key || '';
      let s = 0;
      for (const t of queryTokens) if (sk.includes(t)) s++;
      return { item, score: s };
    })
    .filter(x => x.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, 5)
    .map(x => trim(x.item));

  return JSON.stringify({
    ok: true,
    found: false,
    query: rawQuery,
    intent: merged,
    message: 'No exact match. Closest options below.',
    near_matches: loose,
  });
}

const topScore = scored[0].score;
const tied = scored.filter(x => x.score === topScore).length;

return JSON.stringify({
  ok: true,
  found: true,
  query: rawQuery,
  intent: merged,
  ambiguous: tied > 1,
  match_count: top.length,
  matches: top,
});

const S = require('/files/bot_state_v2.js');
const { logTokens } = require('/files/token_tracker.js');
const gate = $('State Context Injector').first().json;
