// ═══════════════════════════════════════════════════════════════
// ── MEDIA BUNDLER (ZIP) ──
// ═══════════════════════════════════════════════════════════════
const BUNDLER_URL = 'http://media-bundler:3000';
const BUNDLER_TOKEN = 'REPLACE_WITH_YOUR_SECRET';

async function bundleMedia(helpers, mediaUrls, gate) {
  if (!mediaUrls || mediaUrls.length < 2) {
    return { ok: false, reason: 'too_few_files' };
  }
  const files = mediaUrls.map(f => ({
    url: f.url,
    name: f.name || 'file',
    notes: f.notes || '',
    copies: f.copies || null,
    printType: f.printType || null
  }));
  try {
    const resp = await helpers.httpRequest({
      method: 'POST',
      url: `${BUNDLER_URL}/bundle`,
      headers: {
        'Content-Type': 'application/json',
        'X-Internal-Token': BUNDLER_TOKEN
      },
      body: {
        contactKey: gate.contactKey,
        conversationId: gate.conversationId,
        accountId: gate.accountId,
        files,
        options: { preserveDuplicates: true }
      },
      json: true,
      timeout: 300000
    });
    return resp;
  } catch (e) {
    console.error(`[bundleMedia] failed: ${e.message}`);
    return { ok: false, reason: 'service_error', error: String(e.message) };
  }
}

// ── 1. Raw output from agent ─────────────────────────
let output = String(item.output || '').trim();

// ── Log AI Agent token usage BEFORE anything else ──
try {
  const usage =
    item.usage_metadata ||
    item.usageMetadata ||
    (item.metadata && item.metadata.usage_metadata) ||
    (item.response && item.response.usageMetadata) ||
    null;

  if (usage) {
    const promptTokens = Number(
      usage.promptTokenCount ||
      usage.input_tokens ||
      usage.inputTokens ||
      0
    );
    const candidates = Number(usage.candidatesTokenCount || 0);
    const native = usage.candidatesTokenCount != null;
    const completionTokens = native
      ? (usage.totalTokenCount != null ? Math.max(candidates, Number(usage.totalTokenCount)-promptTokens-Number(usage.toolUsePromptTokenCount||0)) : candidates+Number(usage.thoughtsTokenCount||0))
      : Number(usage.output_tokens || usage.outputTokens || 0); // normalized totals already include thinking

    await logTokens({
      provider: 'gemini',
      mode: 'agent',
      prompt: promptTokens,
      completion: completionTokens,
      contactKey: gate.contactKey,
      meta: { model: 'gemini-3.1-flash-lite', source: 'ai_agent' }
    });
  } else {
    console.log('[PrepareReply] no usage_metadata found on agent output');
  }
} catch (e) {
  console.log(`[PrepareReply] token log error: ${String(e.message || e)}`);
}

const latestState = (await S.run(r=>S.get(r,gate.contactKey))) || {};

// ═══════════════════════════════════════════════════════════════
// ── FINALIZE HANDLING ──
// If this batch triggered finalize_order, build the clean final message.
// Never ask a trailing question — this is the bot's last message.
// ═══════════════════════════════════════════════════════════════
if (latestState.lastBotActionBatch === gate.batchId && latestState.lastBotAction === 'finalize' && latestState.confirmedOrder) {
  const o = latestState.confirmedOrder;
  const mediaUrls = (latestState.media && latestState.media.urls) || [];

  const lines = [];
