  lines.push('رقم التواصل: ' + o.phone);
  lines.push('الطلب: ' + o.order);
  if (o.dimensions) lines.push('المقاس: ' + o.dimensions.wCm + '×' + o.dimensions.hCm + ' سم');
  if (o.notes && o.notes !== 'لا يوجد') lines.push('ملاحظات: ' + o.notes);
  if (o.estimatedPrice) lines.push('السعر التقريبي: ' + o.estimatedPrice);
  lines.push('عدد الملفات المستلمة: ' + mediaUrls.length);
  lines.push('');
  lines.push('في انتظار تواصل أحد مندوبي الخدمة لتأكيد التكلفة النهائية والتفاصيل، وبعدها يبدأ التنفيذ.');
  lines.push('');
  lines.push('الأسعار مش شاملة الضريبة.');
  output = lines.join('\n');

  // No trailing question strip needed — template has no question.
  // But apply a defensive strip in case the AI injected anything.
  output = output.replace(/\n+(?:ممكن|هل|تحب|عايز|عاوز|بتقدر|ينفع|ينفعك|محتاج)[^\n]*\?*\s*$/gi, '');
  output = output.replace(/[^\n]*\?\s*$/g, '');
  output = output.trim();
}

// ── 2. Strip leaked signals / JSON / tool_calls ──
output = output
  .replace(/<<<[A-Z_]+(?::[^>]*)?>>>/g, '')
  .replace(/<<<END_ORDER>>>/g, '')
  .replace(/tool_calls\s*:\s*\[[\s\S]*?\]/gi, '')
  .replace(/\b(record_inquiry|record_order_progress|record_feedback|finalize_order|resolve_conversation|abort_order|handoff_to_human|match_product|analyze_media|get_prices)\s*\([^)]*\)/g, '')
  .replace(/\[\s*\w+\s*\([^\]]*\)\s*\]/g, '')
  .replace(/\[call:\s*\]/gi, '')
  .replace(/\[call:[^\]]*\]/gi, '')
  .replace(/```[\s\S]*?```/g, '')
  .trim();

try {
  if (output.startsWith('{') && output.endsWith('}')) {
    const parsed = JSON.parse(output);
    if (typeof parsed.content === 'string') output = parsed.content.trim();
  }
} catch (e) { /* not JSON, keep as-is */ }

// ── 3. Collapse extra blank lines ──
output = output.replace(/\n{3,}/g, '\n\n').trim();

// ── 4. Drop if trivial ──
const TRIVIAL = new Set([
  'تمام', 'أوكي', 'اوكي', 'أوك', 'اوك', 'حسناً', 'حسنا', 'ماشي', 'طيب',
  'ok', 'okay', 'fine', 'good', 'تمام كده', 'حاضر', 'تحت أمرك', 'وصل', 'وصلت'
]);

const normalized = output
  .replace(/[.!؟?]+$/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .toLowerCase();

if (!output) {
  return [];
}

if (TRIVIAL.has(normalized)) {
  return [];
}

// ── 5. SAFETY NET: detect "handoff said but not done" ──
const handoffPhrases = [
  /هحولك\s+لحد\s+من\s+الفريق/,
  /هحولك\s+لفريق/,
  /هحولك\s+لحد\s+من\s+فريقنا/,
  /هحولك\s+للمطبعة/,
  /هحولك\s+للفريق/,
  /الفريق\s+هيتواصل\s+معاك/,
  /معلش\s+على\s+اللبس/
];

const saidHandoff = handoffPhrases.some(p => p.test(output));

if (saidHandoff) {
  const state = (await S.run(r => S.get(r, gate.contactKey))) || {};
  const isHandedOff = state.botDisabledPermanently && (state.state === 'HANDED_OFF' || !!state.confirmedOrder);

  if (!isHandedOff) {
    console.log(`[PrepareReply] Bot said handoff but tool wasn't called. Forcing handoff.`);

    const now = Date.now();
    const baseUrl = gate.baseUrl || state.baseUrl || 'http://chatwoot-rails-1:3000';
    const accountId = gate.accountId || state.accountId;
    const conversationId = gate.conversationId || state.conversationId;

    const confirmedOrder = state.confirmedOrder || null;
    const partialOrder = state.partialOrder || {};
    const customer = state.customer || {};
    const mediaUrls = (state.media && state.media.urls) || [];
    const inquiry = state.inquiry || {};

    const hasOrder = !!(confirmedOrder || partialOrder.orderDetails || partialOrder.name);
    const label = hasOrder ? 'طلب_طباعة' : 'استفسار';

    const lines = [];
    lines.push('🔄 تحويل تلقائي (Safety Net)');
    lines.push('');
    lines.push('السبب: البوت قال "هحولك" من غير ما يستدعي أداة التحويل.');
    lines.push('السياق: ' + output.slice(0, 200));
    lines.push('');

    if (confirmedOrder) {
      lines.push('📋 طلب مؤكد:');
      lines.push('🔑 OrderID: ' + confirmedOrder.orderId);
      lines.push('الاسم: ' + confirmedOrder.name);
      lines.push('رقم التواصل: ' + confirmedOrder.phone);
      lines.push('الطلب: ' + confirmedOrder.order);
    } else if (partialOrder.name || partialOrder.orderDetails) {
      lines.push('📋 بيانات مجمعة:');
      if (partialOrder.name) lines.push('الاسم: ' + partialOrder.name);
      if (partialOrder.phone) lines.push('رقم التواصل: ' + partialOrder.phone);
      if (partialOrder.orderDetails) lines.push('الطلب: ' + partialOrder.orderDetails);
      const designNotes = (partialOrder.designNotes || []).map(n => n.text).filter(Boolean);
      if (designNotes.length > 0) {
        lines.push('ملاحظات التصميم:');
        designNotes.forEach(n => lines.push('  - ' + n));
      }
    } else {
      lines.push('لا توجد بيانات طلب.');
      if (inquiry.topic) lines.push('الاستفسار كان عن: ' + inquiry.topic);
    }

    // ── Try to ZIP the media (fallback to URLs if it fails) ──
    if (mediaUrls.length > 0) {
      const bundle = await bundleMedia(this.helpers, mediaUrls, gate);
      if (bundle.ok) {
        lines.push('');
        lines.push(`📎 الملفات (${mediaUrls.length}) — مرفقة كـ ZIP:`);
        lines.push(bundle.zipUrl);
        lines.push('');
        lines.push('الملفات جوه الـ ZIP:');
        bundle.manifest.forEach(m => lines.push(`- ${m.final}`));
        if (bundle.skipped && bundle.skipped.length > 0) {
          lines.push('');
          lines.push('⚠️ ملفات اتحطت كـ لينك:');
          bundle.skipped.forEach(s => lines.push(`- ${s.name}: ${s.url}  (${s.reason})`));
        }
      } else {
        lines.push('');
        lines.push('📎 الملفات (' + mediaUrls.length + '):');
        mediaUrls.forEach(f => {
          lines.push(`- ${f.name} (${f.type}): ${f.url}`);
        });
      }
    }

    const noteContent = lines.join('\n');

    const lockKey = `actionlock:handoff:${gate.contactKey}`;
    const gotLock = await S.run(r => r.set(lockKey, '1', 'EX', 300, 'NX'));

    if (gotLock === 'OK') {
      await S.run(async r => {
        const push = async (payload) => {
          await r.rpush('pending_actions', JSON.stringify({
            ...payload,
            baseUrl, accountId, conversationId,
            at: now,
            retries: 0
          }));
        };
        await push({ action: 'post_note', content: noteContent });
        await push({ action: 'set_label', label });
        await push({ action: 'toggle_status', status: 'open' });
      });
    } else {
      console.log(`[PrepareReply] Safety net already queued for ${gate.contactKey} — skipping`);
    }

    await S.run(r => S.update(r, gate.contactKey, st => {
      st.state = 'HANDED_OFF';
      st.handoffReason = st.handoffReason || 'safety_net_handoff';
      st.handedOffAt = st.handedOffAt || now;
      st.botDisabledPermanently = true;
      return st;
    }));

    await S.run(r => S.logEvent(r, gate.contactKey, 'handoff', {
      reason: 'safety_net',
      detected_phrase: output.slice(0, 100)
    }));

    console.log(`[PrepareReply] Safety net handoff triggered for ${gate.contactKey}`);
  }
}

