const INVALID_NAMES = new Set([
  'غير محدد', 'unknown', 'لا يوجد', 'none', '?', 'غير معروف', 'n/a',
  'عميل جديد', 'new customer', 'عميل', 'customer', 'ضيف', 'زائر'
]);
const INVALID_PHONES = new Set([
  '0000000000', '1111111111', '2222222222', '3333333333',
  '1234567890', '123456789', '0123456789', '0', '00', '000000000'
]);

await S.run(r => S.update(r, gate.contactKey, st => {
