const S = require('/files/bot_state_v2.js');
const fs = require('fs');

const input = typeof query === 'string' ? JSON.parse(query) : query;
const referenceDescription = String(input.reference_description || '').trim();
const likelyService = String(input.likely_service || '').trim();
const visualKeywords = Array.isArray(input.visual_keywords)
  ? input.visual_keywords.map(k => String(k).trim()).filter(Boolean)
  : [];

if (!referenceDescription && visualKeywords.length === 0) {
  return JSON.stringify({
    ok: false,
    error: 'need_description_or_keywords',
    message: 'محتاج وصف أو كلمات بصرية على الأقل للمطابقة.'
  });
}

// ── Load catalog ──
let catalog;
try {
  catalog = JSON.parse(fs.readFileSync('/files/product_catalogv2.json', 'utf8'));
} catch (e) {
  return JSON.stringify({ ok: false, error: 'catalog_load_failed', detail: String(e.message) });
}

const products = catalog.products || [];
if (products.length === 0) {
  return JSON.stringify({ ok: false, error: 'catalog_empty' });
}

// ── Build compact catalog for Gemini ──
const compactCatalog = products.map(p => ({
  id: p.id,
  name_ar: p.name_ar,
  category: p.category,
  aliases: p.aliases || [],
  visual_keywords_ar: p.visual_keywords_ar || []
}));

// ── Build prompt ──
const prompt = `You are a product matcher for Azzazi Print Shop.

The customer sent a visual reference and we need to find the closest product in our catalog.

Reference details:
- Visual description: "${referenceDescription}"
- Likely service: "${likelyService}"
- Visual keywords: ${JSON.stringify(visualKeywords)}

Catalog (${compactCatalog.length} products):
${JSON.stringify(compactCatalog, null, 2)}

Your task:
Match the reference to the best product(s) in the catalog.

Rules:
1. Compare the reference's visual keywords and description against each product's visual_keywords_ar and aliases.
2. A strong match means: multiple keyword overlaps AND the category fits.
3. Return the top match and 2-3 alternatives.
4. Confidence scale:
   - 0.85-1.0 → very strong match (multiple exact keywords)
   - 0.65-0.84 → strong match (2+ keyword overlaps)
   - 0.45-0.64 → moderate match (1 keyword overlap or category fits)
   - < 0.45 → weak — set matched=false, but still return alternatives
5. If nothing scores >= 0.4, set matched=false and provide the closest alternatives anyway.
6. NEVER invent product IDs. Only use IDs from the catalog.
7. Output JSON only, no extra text.

Output schema:
{
  "matched": true/false,
  "matched_product_id": "bc_couchy_350_nolam" | null,
  "confidence": 0.0,
  "reason": "short Arabic explanation",
  "alternatives": [
    { "id": "...", "confidence": 0.0 }
  ]
}`;

// ── Call Gemini text mode via the n8n webhook ──
let geminiResp;
try {
  geminiResp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://n8n-n8n-1:5678/webhook/REPLACE_WITH_YOUR_SECRET',
    headers: { 'Content-Type': 'application/json' },
    body: { text: prompt },
    json: true,
    timeout: 60000
  });
} catch (e) {
  return JSON.stringify({
    ok: false,
    error: 'gemini_call_failed',
    detail: String(e.message || e).slice(0, 200)
  });
}

if (!geminiResp || geminiResp.error) {
  return JSON.stringify({
    ok: false,
    error: 'gemini_error',
    detail: geminiResp?.error || 'no_response'
  });
}

// ── Enrich with full catalog info ──
const result = {
  matched: !!geminiResp.matched,
  confidence: Number(geminiResp.confidence) || 0,
  reason: String(geminiResp.reason || ''),
  matched_product: null,
  alternatives: []
};

if (result.matched && geminiResp.matched_product_id) {
  const p = products.find(x => x.id === geminiResp.matched_product_id);
  if (p) {
    result.matched_product = {
      id: p.id,
      name_ar: p.name_ar,
      category: p.category,
      prices: p.prices || [],
      notes: p.notes || ''
    };
  } else {
    result.matched = false;
  }
}

if (Array.isArray(geminiResp.alternatives)) {
  for (const alt of geminiResp.alternatives) {
    const p = products.find(x => x.id === alt.id);
    if (!p) continue;
    result.alternatives.push({
      id: p.id,
      name_ar: p.name_ar,
      category: p.category,
      confidence: Number(alt.confidence) || 0,
      prices: p.prices || []
    });
  }
  // limit to 3
  result.alternatives = result.alternatives
    .sort((a, b) => b.confidence - a.confidence)
    .slice(0, 3);
}

return JSON.stringify({ ok: true, ...result });

