const S = require('/files/bot_state_v2.js');
const gate = $('State Context Injector').first().json;
const input = typeof query === 'string' ? JSON.parse(query) : query;
const now = Date.now();

const reason = String(input.reason || 'other').trim().slice(0, 60);
const contextText = String(input.context || '').trim().slice(0, 300);

const state = (await S.run(r => S.get(r, gate.contactKey))) || {};

if (state.confirmedOrder || state.botDisabledPermanently || state.state === 'HANDED_OFF') {
  return JSON.stringify({ ok: true, already: true });
}

const baseUrl = gate.baseUrl || state.baseUrl || 'http://chatwoot-rails-1:3000';
const accountId = gate.accountId || state.accountId;
const conversationId = gate.conversationId || state.conversationId;

const confirmedOrder = state.confirmedOrder || null;
const partialOrder = state.partialOrder || {};
const customer = state.customer || {};
const mediaUrls = (state.media && state.media.urls) || [];
const inquiry = state.inquiry || {};

const hasOrder = !!(confirmedOrder || partialOrder.orderDetails || partialOrder.name);
const label = hasOrder ? 'طلب_طباعة' : 'استفسار';

// ═══════════════════════════════════════════════════════════════
// ── MEDIA BUNDLER (ZIP) ──
// ═══════════════════════════════════════════════════════════════
const BUNDLER_URL = 'http://media-bundler:3000';
const BUNDLER_TOKEN = 'REPLACE_WITH_YOUR_SECRET';

async function bundleMedia(helpers, mediaUrls, gate) {
  if (!mediaUrls || mediaUrls.length < 1) {
    return { ok: false, reason: 'too_few_files' };
  }
  const files = mediaUrls.map(f => ({
    url: f.url,
    name: f.name || 'file',
    notes: f.notes || '',
    copies: f.copies || null,
    printType: f.printType || null
  }));
  try {
    const resp = await helpers.httpRequest({
      method: 'POST',
      url: `${BUNDLER_URL}/bundle`,
      headers: {
        'Content-Type': 'application/json',
        'X-Internal-Token': BUNDLER_TOKEN
      },
      body: {
        contactKey: gate.contactKey,
        conversationId: gate.conversationId,
        accountId: gate.accountId,
        files,
        options: { preserveDuplicates: true }
      },
      json: true,
      timeout: 300000
    });
    return resp;
  } catch (e) {
    console.error(`[bundleMedia] failed: ${e.message}`);
    return { ok: false, reason: 'service_error', error: String(e.message) };
  }
}

// ── build private note ──
const lines = [];
lines.push('🔄 تحويل لفريق بشري');
lines.push('');
lines.push('السبب: ' + reason);
if (contextText) lines.push('السياق: ' + contextText);

if (confirmedOrder) {
  lines.push('');
  lines.push('📋 طلب مؤكد:');
  lines.push('🔑 OrderID: ' + confirmedOrder.orderId + '   (internal only)');
  lines.push('الاسم: ' + confirmedOrder.name);
  lines.push('رقم التواصل: ' + confirmedOrder.phone);
  lines.push('الطلب: ' + confirmedOrder.order);
  if (confirmedOrder.notes && confirmedOrder.notes !== 'لا يوجد') lines.push('ملاحظات: ' + confirmedOrder.notes);
  if (confirmedOrder.estimatedPrice) lines.push('السعر: ' + confirmedOrder.estimatedPrice);
} else if (partialOrder.name || partialOrder.orderDetails) {
  lines.push('');
  lines.push('📋 بيانات مجمعة (الطلب لسه ما اتأكدش):');
  if (partialOrder.name) lines.push('الاسم: ' + partialOrder.name);
  if (partialOrder.phone) lines.push('رقم التواصل: ' + partialOrder.phone);
  else if (customer.whatsappPhone) lines.push('رقم التواصل (واتساب): ' + customer.whatsappPhone);
  if (partialOrder.orderDetails) lines.push('الطلب: ' + partialOrder.orderDetails);
  if (partialOrder.dimensions?.wCm && partialOrder.dimensions?.hCm) {
    lines.push('المقاس: ' + partialOrder.dimensions.wCm + '×' + partialOrder.dimensions.hCm + ' سم');
  }
  const designNotes = (partialOrder.designNotes || []).map(n => n.text).filter(Boolean);
  if (designNotes.length > 0) {
    lines.push('ملاحظات التصميم:');
    designNotes.forEach(n => lines.push('  - ' + n));
  }
} else {
  lines.push('');
  lines.push('لا توجد بيانات طلب.');
  if (inquiry.topic) lines.push('العميل كان يسأل عن: ' + inquiry.topic);
  if (inquiry.quotedPrices?.length > 0) {
    lines.push('عروض سعر اتقالت:');
    inquiry.quotedPrices.forEach(p => lines.push('  - ' + p.item + ': ' + p.price));
  }
}

// ── Try to ZIP the media (fallback to URLs if it fails) ──
if (mediaUrls.length > 0) {
  const bundle = await bundleMedia(this.helpers, mediaUrls, gate);
  if (bundle.ok) {
    lines.push('');
    lines.push(`📎 الملفات (${mediaUrls.length}) — مرفقة كـ ZIP:`);
    lines.push(bundle.zipUrl);
    lines.push('');
    lines.push('الملفات جوه الـ ZIP:');
    bundle.manifest.forEach(m => lines.push(`- ${m.final}`));
    if (bundle.skipped && bundle.skipped.length > 0) {
      lines.push('');
      lines.push('⚠️ ملفات اتحطت كـ لينك (فشل التحميل):');
      bundle.skipped.forEach(s => lines.push(`- ${s.name}: ${s.url}  (${s.reason})`));
    }
  } else {
    lines.push('');
    lines.push('📎 الملفات/الروابط (' + mediaUrls.length + '):');
    mediaUrls.forEach(f => {
      const src = f.source === 'internal_note' ? 'agent-note' : 'customer';
      const analyzedTag = f.analyzed?.type ? ` [${f.analyzed.type}]` : '';
      lines.push(`- ${f.name} (${f.type}${analyzedTag}, ${src}): ${f.url}`);
    });
  }
}

if (state.feedback?.sentiment === 'negative' && state.feedback.history?.length > 0) {
  const recent = state.feedback.history.slice(-2);
  lines.push('');
  lines.push('⚠️ ملاحظات سلبية حديثة:');
  recent.forEach(f => lines.push(`  - "${f.text || '(بدون نص)'}"`));
}

const noteContent = lines.join('\n');

// ── Idempotency lock ──
const lockKey = `actionlock:handoff:${gate.contactKey}`;
const gotLock = await S.run(r => r.set(lockKey, '1', 'EX', 300, 'NX'));

if (gotLock === 'OK') {
  await S.run(async r => {
    const push = async (payload) => {
      await r.rpush('pending_actions', JSON.stringify({
        ...payload,
        baseUrl, accountId, conversationId,
        at: now,
        retries: 0
      }));
    };
    await push({ action: 'post_note', content: noteContent });
    await push({ action: 'set_label', label });
    await push({ action: 'toggle_status', status: 'open' });
  });
} else {
  console.log(`[handoff_to_human] Already queued for ${gate.contactKey} — skipping duplicate push`);
}

// ── archive state snapshot ──
await S.run(async r => {
  const snap = await S.get(r, gate.contactKey);
  if (snap) {
    await r.set(`archived:${gate.contactKey}:${now}`, JSON.stringify(snap), 'EX', 31536000);
  }
});

// ── write handoff record ──
await S.run(async r => {
  const k = `handoff:${gate.contactKey}:${now}`;
  await r.set(k, JSON.stringify({
    reason, context: contextText, at: now, hasOrder,
    orderId: confirmedOrder?.orderId || null,
    label, contactKey: gate.contactKey, conversationId
  }), 'EX', 7776000);
});

// ── update state + set permanent disable ──
await S.run(r => S.update(r, gate.contactKey, st => {
  st.state = 'HANDED_OFF';
  st.lastBotActionBatch = gate.batchId;
  st.lastBotAction = 'handoff';
  st.handoffReason = reason;
  st.handedOffAt = now;
  st.botDisabledPermanently = true;
  return st;
}));

await S.run(r => S.logEvent(r, gate.contactKey, 'handoff', { reason, hasOrder }));

return JSON.stringify({
  ok: true,
  label,
  reason,
  hasOrder,
  orderId: confirmedOrder?.orderId || null
});

