if st.status ~= 'pending' or tostring(st.executionId) ~= ARGV[1] then return -1 end
redis.call('SET', KEYS[1], ARGV[2], 'EX', 2592000)
redis.call('INCR', KEYS[2])
redis.call('EXPIRE', KEYS[2], 7776000)
return 1
`,2,prepared.sendKey,counter,String($execution.id),JSON.stringify({status:'submitted',messageId:response.id,executionId:String($execution.id),at:Date.now()})));
