  st.resolvedAt = st.resolvedAt || Date.now();
  st.botDisabledPermanently = true;
  return st;
}));

// 3) Log the event
await S.run(r => S.logEvent(r, gate.contactKey, 'conversation_resolved', {
  reason: 'number_deprecation_notice',
  inboxId: gate.inboxId
}));

return [{ json: { ok: true, contactKey: gate.contactKey } }];
